import test from 'node:test';
import assert from 'node:assert/strict';
import { createCreditNote } from '../src/credits.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('createCreditNote creates a credit note for an issued invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r = createCreditNote(issued, { amount: 5000, reason: 'Discount applied', date: '2026-10-20' }, []);
  assert.equal(r.ok, true);
  const cn = r.value;
  assert.equal(cn.number, 'CN-2026-0001');
  assert.equal(cn.invoiceNumber, 'INV-2026-0001');
  assert.equal(cn.customerId, 'C-001');
  assert.equal(cn.amount, 5000);
  assert.equal(cn.reason, 'Discount applied');
  assert.equal(cn.date, '2026-10-20');
});

test('createCreditNote works on partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 10000, date: '2026-10-15' }).value;

  const r = createCreditNote(partial, { amount: 5000, reason: 'Partial refund', date: '2026-10-20' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
});

test('createCreditNote works on paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const paid = recordPayment(issued, { amount: 48854, date: '2026-10-15' }).value;

  const r = createCreditNote(paid, { amount: 5000, reason: 'Refund requested', date: '2026-10-20' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
});

test('createCreditNote reports NOT_ISSUED for draft invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const r = createCreditNote(inv, { amount: 5000, reason: 'Discount applied', date: '2026-10-20' }, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote reports AMOUNT_INVALID for non-integer amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r = createCreditNote(issued, { amount: 5000.5, reason: 'Discount applied', date: '2026-10-20' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote reports AMOUNT_INVALID for zero amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r = createCreditNote(issued, { amount: 0, reason: 'Discount applied', date: '2026-10-20' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote reports AMOUNT_INVALID for negative amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r = createCreditNote(issued, { amount: -5000, reason: 'Discount applied', date: '2026-10-20' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote reports CREDIT_TOO_HIGH if amount exceeds invoice total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r = createCreditNote(issued, { amount: 50000, reason: 'Discount applied', date: '2026-10-20' }, []);
  assert.deepEqual(r, { ok: false, error: 'CREDIT_TOO_HIGH' });
});

test('createCreditNote allows credit up to invoice total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r = createCreditNote(issued, { amount: 48854, reason: 'Full refund', date: '2026-10-20' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.amount, 48854);
});

test('createCreditNote increments counter within same year', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const r1 = createCreditNote(issued1, { amount: 5000, reason: 'Refund', date: '2026-10-20' }, []);
  assert.equal(r1.value.number, 'CN-2026-0001');

  const r2 = createCreditNote(issued2, { amount: 3000, reason: 'Refund', date: '2026-10-25' }, ['CN-2026-0001']);
  assert.equal(r2.value.number, 'CN-2026-0002');
});

test('createCreditNote restarts counter for new year', () => {
  const inv2025 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-20',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued2025 = issueInvoice(inv2025, []).value;

  const inv2026 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued2026 = issueInvoice(inv2026, ['INV-2025-0001']).value;

  const r2025 = createCreditNote(issued2025, { amount: 5000, reason: 'Refund', date: '2025-12-25' }, []);
  assert.equal(r2025.value.number, 'CN-2025-0001');

  const r2026 = createCreditNote(issued2026, { amount: 3000, reason: 'Refund', date: '2026-01-20' }, ['CN-2025-0001']);
  assert.equal(r2026.value.number, 'CN-2026-0001');
});

test('createCreditNote handles mixed invoice and credit note numbers', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const existingNumbers = [
    'INV-2026-0001',
    'INV-2026-0002',
    'CN-2026-0001',
    'INV-2026-0003',
    'CN-2026-0002',
  ];

  const r = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2026-10-20' }, existingNumbers);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0003');
});

test('createCreditNote pads counter to 4 digits', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const existingNumbers = Array.from({ length: 99 }, (_, i) => `CN-2026-${String(i + 1).padStart(4, '0')}`);

  const r = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2026-10-20' }, existingNumbers);
  assert.equal(r.value.number, 'CN-2026-0100');
});

test('createCreditNote finds max counter correctly with unordered numbers', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const existingNumbers = [
    'CN-2026-0005',
    'CN-2026-0001',
    'CN-2026-0003',
  ];

  const r = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2026-10-20' }, existingNumbers);
  assert.equal(r.value.number, 'CN-2026-0006');
});

test('createCreditNote ignores numbers from other years', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const existingNumbers = [
    'CN-2025-9999',
    'CN-2026-0001',
    'CN-2027-0001',
  ];

  const r = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2026-10-20' }, existingNumbers);
  assert.equal(r.value.number, 'CN-2026-0002');
});

test('createCreditNote preserves invoice and customer info', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2026-10-20' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.invoiceNumber, 'INV-2026-0001');
  assert.equal(r.value.customerId, 'C-003');
});

test('createCreditNote works with complex invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r = createCreditNote(issued, { amount: 20000, reason: 'Partial refund', date: '2026-10-20' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.amount, 20000);
});

test('createCreditNote uses different date from invoice issue date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2026-10-30' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.date, '2026-10-30');
});

test('createCreditNote with date in different year gets correct prefix', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-12-20',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2027-01-15' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2027-0001');
});

test('createCreditNote works with small and large amounts', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r1 = createCreditNote(issued, { amount: 1, reason: 'Tiny refund', date: '2026-10-20' }, []);
  assert.equal(r1.ok, true);
  assert.equal(r1.value.amount, 1);

  const r2 = createCreditNote(issued, { amount: 48854, reason: 'Full refund', date: '2026-10-21' }, ['CN-2026-0001']);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.amount, 48854);
});

test('createCreditNote with various reason texts', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const reasons = [
    'Customer requested refund',
    'Service not provided',
    'Invoice duplicate - cancellation',
    'Adjustment for overcharge',
  ];

  for (let i = 0; i < reasons.length; i++) {
    const r = createCreditNote(issued, { amount: 5000, reason: reasons[i], date: '2026-10-20' },
      Array.from({ length: i }, (_, j) => `CN-2026-${String(j + 1).padStart(4, '0')}`));
    assert.equal(r.ok, true);
    assert.equal(r.value.reason, reasons[i]);
  }
});

test('createCreditNote works on invoice with payments and discounts', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 30000, date: '2026-10-15' }).value;

  const r = createCreditNote(partial, { amount: 15000, reason: 'Service adjustment', date: '2026-10-20' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
  assert.equal(r.value.amount, 15000);
});

